import { NgIf, NgTemplateOutlet } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  HostBinding,
  HostListener,
  Input,
  ViewEncapsulation,
  booleanAttribute,
  inject,
} from '@angular/core';
import {
  QAnalyticsService,
  QPlatformService,
} from '@questrade/allspark-angular-components/core/services';
import { ENTER, SPACE } from '@questrade/allspark-angular-components/core/utils';
import { QIconComponent, QIconSize } from '@questrade/allspark-angular-components/icon';
import { QSpinnerComponent, QSpinnerSize } from '@questrade/allspark-angular-components/spinner';
import { QButtonClickAnalyticsEvent } from './types/button-click-analytics-event.type';
import { QButtonIconPosition } from './types/button-icon-position.type';
import { QButtonSize } from './types/button-size.type';
import { QButtonVariant } from './types/button-variant.type';

@Component({
  imports: [NgIf, NgTemplateOutlet, QIconComponent, QSpinnerComponent],
  selector: `
    button[q-button],
    button[q-text-button],
    button[q-icon-button],
  `,
  templateUrl: './button.component.html',
  styleUrls: ['./button.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QButtonComponent {
  @Input() icon = '';
  @Input() loadingText = '';
  @Input() size: QButtonSize = 'medium';
  @Input() variant: QButtonVariant = 'primary';
  @Input() iconPosition: QButtonIconPosition = 'left';
  @Input({ transform: booleanAttribute }) @HostBinding('class.q-button-loading') loading = false;
  @Input({ transform: booleanAttribute }) analyticsCssClassIdentifier = true;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-button';

  @Input({ transform: booleanAttribute })
  @HostBinding('attr.disabled')
  get disabled(): boolean | null {
    return this._disabled || null;
  }
  set disabled(value: boolean | null) {
    this._disabled = value;
  }

  @HostBinding('attr.tabindex') get tabindexAttr(): number | null {
    const index = this._platform.SAFARI ? 0 : null;
    return this.disabled ? -1 : index;
  }

  @HostBinding('attr.aria-disabled') get ariaDisabledAttr(): boolean {
    return this.loading;
  }

  @HostBinding('class') get classNames(): string {
    return [
      'q-button',
      'q-focus-indicator',
      `q-button-${this.variant}`,
      `q-button-${this.size}`,
      this.icon && `icon-${this.iconPosition}`,
      this.loading && 'q-button-loading',
      this._active && 'q-button-active',
      this.loadingText && 'q-button-loading-text',
      this._isTextButton() && 'q-text-button',
      this._isIconButton() && 'q-icon-button',
      this._analytics.isEnabled && this.analyticsCssClassIdentifier && 'q-analytics',
    ]
      .filter(Boolean)
      .join(' ');
  }

  @HostListener('keydown', ['$event']) _onKeyDown({ code }: KeyboardEvent): void {
    if (this.disabled) return;

    if ([SPACE, ENTER].includes(code)) {
      this._active = true;
    }
  }

  @HostListener('keyup', ['$event']) _onKeyUp({ code }: KeyboardEvent): void {
    if (this.disabled) return;

    if ([SPACE, ENTER].includes(code)) {
      this._active = false;
    }
  }

  @HostListener('click') _onClick(): void {
    this._sendAnalyticsEvent(this._elementRef.nativeElement);
  }

  private _active = false;
  private _disabled: boolean | null = null;
  private readonly _platform = inject(QPlatformService);
  private readonly _elementRef = inject(ElementRef);
  private readonly _analytics = inject(QAnalyticsService);

  _isTextButton(): boolean {
    return this._elementRef.nativeElement.hasAttribute('q-text-button');
  }

  _isIconButton(): boolean {
    return this._elementRef.nativeElement.hasAttribute('q-icon-button');
  }

  _isSecondary(): boolean {
    return this.variant === 'secondary';
  }

  get spinnerSize(): QSpinnerSize {
    return this.size === 'medium' ? 'small' : 'x-small';
  }

  get iconSize(): QIconSize {
    return this.size === 'small' ? '20' : '24';
  }

  private _sendAnalyticsEvent(hostElement: HTMLButtonElement): void {
    const hostElementDataQt = hostElement.dataset.qt ? `${hostElement.dataset.qt}_` : '';
    const event: QButtonClickAnalyticsEvent = {
      event: 'button_click',
      link_text: hostElement.innerText,
      link_classes: hostElement.classList.value,
      button_name: `${hostElementDataQt}${hostElement.innerText}`,
    };
    this._analytics.sendEvent(event);
  }
}
